{"result":{"meta":null,"content":"CREATE TABLE IF NOT EXISTS restaurant_config (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());\nCREATE TABLE IF NOT EXISTS restaurant_customers (phone TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT 'Guest', points INTEGER NOT NULL DEFAULT 0, visits INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'New', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());\nCREATE TABLE IF NOT EXISTS restaurant_orders (id TEXT PRIMARY KEY, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', verified BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());\nCREATE INDEX IF NOT EXISTS idx_restaurant_orders_created ON restaurant_orders(created_at DESC);\nCREATE TABLE IF NOT EXISTS restaurant_tables (number INTEGER PRIMARY KEY, seats INTEGER NOT NULL DEFAULT 4, status TEXT NOT NULL DEFAULT 'Available', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());\nCREATE TABLE IF NOT EXISTS restaurant_bookings (id TEXT PRIMARY KEY, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'Booked', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());","structuredContent":null,"isError":false,"path":"migrations/0001_restaurant_pos.sql","hash":"751afc8e5cfa322419a09dd19547d8b0e2dfb1a93f828e0be641ea2aae6125a4","total_lines":6},"error":null,"error_data":null,"error_code":null,"classification_id":null,"json_rpc_error_code":null,"error_http_status_code":null,"error_http_headers":null,"internal":{"external_call_time_ms":780},"clamp_errors":null,"clamp_rewrites":null,"connector_id":"asdk_app_69e39e675b348191a4d52cf2bc580b79","connector_name":"Hatchable","action_name":"read_file","is_sync":false}